// Inline server/viewer-md.js into server/viewer.html and emit the result as a
// TS string module, so the Worker can serve the page with zero build tooling.
const [html, mdJs] = await Promise.all([
  Bun.file("server/viewer.html").text(),
  Bun.file("server/viewer-md.js").text(),
]);
const merged = html.replace("<!-- inject:viewer-md.js -->", "<script>\n" + mdJs + "\n</script>");
if (merged === html) throw new Error("viewer.html is missing the inject:viewer-md.js placeholder");
await Bun.write(
  "server/viewer-html.ts",
  "// GENERATED by scripts/gen-viewer.ts — do not edit. Edit viewer.html / viewer-md.js and run: bun run gen\n" +
    "export default " + JSON.stringify(merged) + ";\n",
);
console.log("generated server/viewer-html.ts");
